




class Solution:
    def addStrings(self, num1: str, num2: str) -> str:
        import sys
        
        sys.set_int_max_str_digits(100000)
        
        return str(int(num1) + int(num2))
    
    
tests = []

tests.append({
    "input": {
        "num1": "11",
        "num2": "123"
    },
    "output": "134"
})


tests.append({
    "input": {
        "num1": "456",
        "num2": "77"
    },
    "output": "533"
})


tests.append({
    "input": {
        "num1": "0",
        "num2": "0"
    },
    "output": "0"
})


tests.append({
    "input": {
        "num1": "1",
        "num2": ""
    },
    "output": "0"
})




for test in tests:
    print(Solution().addStrings(**test["input"]) == test["output"])